import { useField } from 'formik';
// UI Kit'ten import edin: import { TextField } from "@/components/ui/text-field"
// Bu component UI Kit'e bağlıdır — npx msi-ui-cli add text-field ile kurun

interface FormikTextFieldProps {
  name: string;
  label?: string;
  placeholder?: string;
  type?: string;
  disabled?: boolean;
  className?: string;
}

/**
 * Formik bağlantılı TextField.
 * Hata mesajı ve touched durumunu otomatik yönetir.
 *
 * @example
 * <FormikTextField name="email" label="E-posta" type="email" />
 */
export function FormikTextField({
  name,
  label,
  placeholder,
  type = 'text',
  disabled,
  className,
}: FormikTextFieldProps) {
  const [field, meta] = useField(name);

  return (
    <div className={className}>
      {label && (
        <label htmlFor={name} className="mb-1 block text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label}
        </label>
      )}
      <input
        {...field}
        id={name}
        type={type}
        placeholder={placeholder}
        disabled={disabled}
        className="w-full rounded-lg border border-neutral-300 bg-white px-3 py-2 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 disabled:cursor-not-allowed disabled:opacity-60 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-100"
      />
      {meta.touched && meta.error && (
        <p className="mt-1 text-xs text-red-500">{meta.error}</p>
      )}
    </div>
  );
}

import { useField } from 'formik';

interface Option {
  value: string | number;
  label: string;
}

interface FormikSelectProps {
  name: string;
  label?: string;
  options: Option[];
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

/**
 * Formik bağlantılı Select.
 *
 * @example
 * <FormikSelect name="role" label="Rol" options={[{ value: 'admin', label: 'Admin' }]} />
 */
export function FormikSelect({
  name,
  label,
  options,
  placeholder = 'Seçiniz...',
  disabled,
  className,
}: FormikSelectProps) {
  const [field, meta] = useField(name);

  return (
    <div className={className}>
      {label && (
        <label htmlFor={name} className="mb-1 block text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label}
        </label>
      )}
      <select
        {...field}
        id={name}
        disabled={disabled}
        className="w-full rounded-lg border border-neutral-300 bg-white px-3 py-2 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 disabled:cursor-not-allowed disabled:opacity-60 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-100"
      >
        <option value="">{placeholder}</option>
        {options.map((opt) => (
          <option key={opt.value} value={opt.value}>
            {opt.label}
          </option>
        ))}
      </select>
      {meta.touched && meta.error && (
        <p className="mt-1 text-xs text-red-500">{meta.error}</p>
      )}
    </div>
  );
}

import { useField } from 'formik';

interface FormikCheckboxProps {
  name: string;
  label: string;
  disabled?: boolean;
  className?: string;
}

export function FormikCheckbox({ name, label, disabled, className }: FormikCheckboxProps) {
  const [field, meta] = useField({ name, type: 'checkbox' });

  return (
    <div className={className}>
      <label className="flex cursor-pointer items-center gap-2 text-sm text-neutral-700 dark:text-neutral-300">
        <input
          {...field}
          type="checkbox"
          disabled={disabled}
          className="h-4 w-4 rounded border-neutral-300 accent-primary disabled:cursor-not-allowed"
        />
        {label}
      </label>
      {meta.touched && meta.error && (
        <p className="mt-1 text-xs text-red-500">{meta.error}</p>
      )}
    </div>
  );
}

import { useField, useFormikContext } from 'formik';

interface FormikDatePickerProps {
  name: string;
  label?: string;
  disabled?: boolean;
  min?: string;
  max?: string;
  className?: string;
}

export function FormikDatePicker({
  name,
  label,
  disabled,
  min,
  max,
  className,
}: FormikDatePickerProps) {
  const [field, meta] = useField(name);
  const { setFieldValue } = useFormikContext();

  return (
    <div className={className}>
      {label && (
        <label htmlFor={name} className="mb-1 block text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label}
        </label>
      )}
      <input
        {...field}
        id={name}
        type="date"
        min={min}
        max={max}
        disabled={disabled}
        onChange={(e) => setFieldValue(name, e.target.value)}
        className="w-full rounded-lg border border-neutral-300 bg-white px-3 py-2 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 disabled:cursor-not-allowed disabled:opacity-60 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-100"
      />
      {meta.touched && meta.error && (
        <p className="mt-1 text-xs text-red-500">{meta.error}</p>
      )}
    </div>
  );
}

import { useField } from 'formik';

interface Option {
  value: string | number;
  label: string;
}

interface FormikRadioButtonsProps {
  name: string;
  label?: string;
  options: Option[];
  disabled?: boolean;
  className?: string;
}

export function FormikRadioButtons({
  name,
  label,
  options,
  disabled,
  className,
}: FormikRadioButtonsProps) {
  const [field, meta] = useField(name);

  return (
    <div className={className}>
      {label && (
        <span className="mb-2 block text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label}
        </span>
      )}
      <div className="flex flex-wrap gap-4">
        {options.map((opt) => (
          <label
            key={opt.value}
            className="flex cursor-pointer items-center gap-2 text-sm text-neutral-700 dark:text-neutral-300"
          >
            <input
              type="radio"
              name={field.name}
              value={opt.value}
              checked={field.value === opt.value}
              onChange={field.onChange}
              onBlur={field.onBlur}
              disabled={disabled}
              className="h-4 w-4 accent-primary disabled:cursor-not-allowed"
            />
            {opt.label}
          </label>
        ))}
      </div>
      {meta.touched && meta.error && (
        <p className="mt-1 text-xs text-red-500">{meta.error}</p>
      )}
    </div>
  );
}

export { FormikTextField } from './formik-text-field';
export { FormikSelect } from './formik-select';
export { FormikCheckbox } from './formik-checkbox';
export { FormikDatePicker } from './formik-date-picker';
export { FormikRadioButtons } from './formik-radio-buttons';
